const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=(v,d=1)=>v==null?'—':Number(v).toLocaleString('ro-RO',{maximumFractionDigits:d});
let m=example(),page='overview',diagramId='main',selected='',selectedEdge='',zoom=1,result=null,baseline=null,busy=false,worker,undo=[],redo=[],connectFrom='',search='',storageNote='';
try{const v2=localStorage.getItem(storageKey),v1=qaMode?null:localStorage.getItem('factory-studio-v1');if(v2||v1){m=migrate(JSON.parse(v2||v1));validateModel(m);diagramId=m.diagrams[0]?.id;if(!v2)storageNote='Modelul v0.1 a fost migrat. Copia originală este păstrată în browser.'}}catch(e){storageNote='Datele salvate nu au putut fi încărcate: '+e.message+'. Nu au fost suprascrise.'}
const kindNames=Object.fromEntries(Object.entries(DIAGRAMS).filter(([,v])=>v.status!=='planned').map(([k,v])=>[k,v.name]));
let librarySearch='',portFrom=null;
function toast(t){$('.toast')?.remove();const e=document.createElement('div');e.className='toast';e.textContent=t;document.body.append(e);setTimeout(()=>e.remove(),6000)}
function save(){try{localStorage.setItem(storageKey,JSON.stringify(m))}catch{toast('Stocare indisponibilă: exportă modelul JSON.')}}
function change(fn,{layout=false}={}){lastChangeError='';if(busy){toast('Anulează simularea înainte de editare.');return}const old=structuredClone(m);try{fn();validateModel(m);undo.push(old);if(undo.length>50)undo.shift();redo=[];if(!layout)result=null;save();render();return true}catch(e){m=old;lastChangeError=e.message;toast(e.message);render();return false}}
function diagram(){return m.diagrams.find(d=>d.id===diagramId)||m.diagrams[0]}
function n(id){return m.nodes.find(n=>n.id===id)}
function download(name,data,type='application/json'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),5000)}
function dialog(title,html,callback){const c=document.createElement('div');c.className='cover';c.setAttribute('role','dialog');c.setAttribute('aria-modal','true');c.setAttribute('aria-label',title);c.innerHTML=`<form class="dialog"><div class="panelhead"><h2>${esc(title)}</h2><button type="button" data-close>✕</button></div>${html}<div class="row"><button type="submit" class="primary">Aplică</button><button type="button" data-close>Anulează</button></div><p class="small error" id="form-error"></p></form>`;document.body.append(c);c.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>c.remove());c.querySelector('form').onsubmit=e=>{e.preventDefault();try{lastChangeError='';callback(Object.fromEntries(new FormData(e.target)));if(lastChangeError)throw Error(lastChangeError);c.remove()}catch(err){c.querySelector('#form-error').textContent=err.message}};c.querySelector('input,select,textarea')?.focus();c.onkeydown=e=>{if(e.key!=='Tab')return;const a=[...c.querySelectorAll('button,input,select,textarea')].filter(x=>!x.disabled&&x.getClientRects().length);if(e.shiftKey&&document.activeElement===a[0]){e.preventDefault();a.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===a.at(-1)){e.preventDefault();a[0].focus()}}}
function selectOptions(items,value){return items.map(([k,v])=>`<option value="${esc(k)}" ${k===value?'selected':''}>${esc(v)}</option>`).join('')}
function header(){return topbar({m,role,busy,undo,redo,runtime,cloudRevision})}
function nav(){return navigation({page,role,runtime})}
function controls(){return simulationControls({m,busy,runtime})}
function render(){const functions={bibliography:bibliographyView,overview:()=>overviewView({m,result,role,baseline}),operator:()=>operatorView({m,operationId:operatorOperation}),calibration:()=>calibrationView({m}),library:libraryView,staffing:staffingView,engineering:engineeringView,diagrams:diagramsView,repository:repositoryView,variables:variablesView,results:resultsView,scenarios:scenariosView,method:methodView};$('#app').innerHTML=`<div class="shell">${nav()}<main class="main">${header()}<div class="studio-workspace ${page==='diagrams'?'is-diagram':''}">${storageNote?`<div class="notice">${esc(storageNote)}</div>`:''}${page==='operator'?'':controls()}${functions[page]()}</div></main></div><input type="file" id="file" hidden accept=".json,application/json">`;bind();bindV04();}
function diagramsView(){const d=diagram();if(!DIAGRAMS[d.kind].relations.includes(connectionType))connectionType=DIAGRAMS[d.kind].relations[0];return renderDiagrams({m,d,zoom,selected,connectMode,connectFrom,connectionType,colorMode,focusSelection,canvas:diagramSvg(),inspector:inspector()})}
function inspector(){return renderInspector({m,selected,selectedEdge})}

function repositoryView(){return render_repositoryView({m,result,baseline,search})}
function variablesView(){return render_variablesView({m,result,baseline,search})}
function resultsView(){return render_resultsView({m,result,baseline,search})}
function scenariosView(){return render_scenariosView({m,result,baseline,search})}
function methodView(){return render_methodView({m,result,baseline,search})}
function newNode(type){dialog('Creează '+TYPES[type],'<label>Nume<input name="name" required maxlength="160"></label>',d=>change(()=>{const el=node(type,d.name);initializeProvenance(el);m.nodes.push(el);if(diagram()){const count=diagram().items.length;diagram().items.push({nodeId:el.id,x:40+count%5*235,y:70+Math.floor(count/5)*150})}selected=el.id;selectedEdge='';page='diagrams'}))}
function variableDialog(id){const v=m.variables.find(v=>v.id===id);dialog(v?'Editează variabila':'Variabilă nouă',`<label>Nume<input name="name" required value="${esc(v?.name||'')}"></label><label>Valoare<input name="value" type="number" step="any" value="${v?.value??0}" required></label><label>Unitate<select name="unit">${selectOptions([...new Set(Object.values(FIELDS).map(f=>f[1]))].map(x=>[x,x]),v?.unit||'s')}</select></label>`,d=>change(()=>{const val={id:v?.id||uid('var'),name:d.name,value:+d.value,unit:d.unit};if(v)Object.assign(v,val);else m.variables.push(val)}))}
function action(a){if(!busy&&(actionV04(a)||engineeringAction(a)))return;if(busy&&!['cancel','export','results-json'].includes(a)){toast('Anulează simularea înainte de editare.');return}
 if(a==='run'){try{validateModel(m,{simulation:true})}catch(e){toast(e.message);return}busy=true;const runId=++simulationRunId;render();worker=startSimulation(structuredClone(m),runtime,data=>{if(runId!==simulationRunId)return;busy=false;result=data;page='results';render();toast('Simulare finalizată.')},error=>{if(runId!==simulationRunId)return;busy=false;render();toast(error)});return}
 if(a==='cancel'){simulationRunId++;worker?.terminate();busy=false;render();return}if(a==='export')return download('factory-studio-v2.json',JSON.stringify(m,null,2));if(a==='import')return $('#file').click();
 if(a==='undo'||a==='redo'){const from=a==='undo'?undo:redo,to=a==='undo'?redo:undo;if(from.length){to.push(structuredClone(m));m=from.pop();cloudId='';cloudRevision=0;result=null;save();render()}return}
 if(a==='new-model')return dialog('Înlocuiește modelul curent','<p>Exportă modelul curent înainte de înlocuire. Poți reveni cu Undo în această sesiune.</p><label>Nume<input name="name" value="Fabrica mea" required></label><label>Conținut<select name="mode"><option value="blank">Model gol</option><option value="demo">Exemplu integrat cu personal, HW, SW și rework</option></select></label>',d=>change(()=>{m=d.mode==='demo'?example():emptyModel();m.name=d.name;selected='';selectedEdge='';diagramId=m.diagrams[0].id;storageNote='';baseline=null;cloudId='';cloudRevision=0;initializeAll()}));
 if(a==='new-node')return newNode($('#new-type').value);if(a==='repo-new')return dialog('Tip element',`<label>Tip<select name="type">${selectOptions(Object.entries(TYPES),'operation')}</select></label>`,d=>newNode(d.type));
 if(a==='existing')return dialog('Adaugă o reprezentare',`<label>Element<select name="id">${selectOptions(m.nodes.filter(n=>!diagram().items.some(i=>i.nodeId===n.id)).map(n=>[n.id,n.name]),'')}</select></label>`,d=>{if(!d.id)throw Error('Toate elementele sunt deja prezente.');change(()=>diagram().items.push({nodeId:d.id,x:80,y:80}),{layout:true})});
 if(a==='new-diagram')return dialog('Diagramă nouă',`<label>Nume<input name="name" required></label><label>Tip<select name="kind">${selectOptions(Object.entries(kindNames),'process')}</select></label><label>Conținut<select name="contents"><option value="empty">Goală</option><option value="all">Toate elementele existente</option></select></label>`,d=>change(()=>{const id=uid('diagram');m.diagrams.push({id,name:d.name,kind:d.kind,items:d.contents==='all'?m.nodes.map((n,i)=>({nodeId:n.id,x:40+i%5*235,y:70+Math.floor(i/5)*150})):[]});diagramId=id;selected='';selectedEdge=''},{layout:true}));
 if(a==='rename-diagram')return dialog('Proprietăți diagramă',`<label>Nume<input name="name" value="${esc(diagram().name)}" required></label><label>Tip<select name="kind">${selectOptions(Object.entries(kindNames),diagram().kind)}</select></label>`,d=>change(()=>Object.assign(diagram(),d),{layout:true}));
 if(a==='delete-diagram')return change(()=>{if(m.diagrams.length===1)throw Error('Păstrează cel puțin o diagramă.');m.diagrams=m.diagrams.filter(d=>d.id!==diagram().id);diagramId=m.diagrams[0].id},{layout:true});
 if(a==='layout')return change(()=>diagram().items.forEach((p,i)=>{p.x=40+i%5*235;p.y=70+Math.floor(i/5)*150}),{layout:true});
 if(a==='zoom-in'||a==='zoom-out'){zoom=Math.max(.1,Math.min(1.5,zoom+(a==='zoom-in'?.1:-.1)));render();return}
 if(a==='svg'){const svg=$('#diagram-canvas').cloneNode(true);svg.setAttribute('xmlns','http://www.w3.org/2000/svg');svg.querySelectorAll('text').forEach(t=>{t.setAttribute('font-family','Arial');t.setAttribute('font-size',t.classList.contains('node-name')?'13':'10')});return download('diagram.svg',new XMLSerializer().serializeToString(svg),'image/svg+xml')}
 if(a==='connect'){if(connectFrom){connectFrom='';render();return}if(!selected){toast('Selectează mai întâi elementul sursă.');return}connectFrom=selected;const type=$('#relation-type').value;render();$('#relation-type').value=type;return}
 if(a==='hide-node')return change(()=>diagram().items=diagram().items.filter(i=>i.nodeId!==selected),{layout:true});
 if(a==='delete-node'){const id=selected,related=m.edges.filter(e=>e.from===id||e.to===id).length;return dialog('Șterge elementul din model',`<p>${esc(n(id).name)}: vor fi eliminate ${related} relații și toate reprezentările. Copiii vor deveni rădăcini. Undo permite revenirea.</p>`,()=>change(()=>{m.nodes=m.nodes.filter(x=>x.id!==id);m.nodes.forEach(x=>{if(x.parent===id)x.parent=''});m.edges=m.edges.filter(e=>e.from!==id&&e.to!==id);m.diagrams.forEach(d=>d.items=d.items.filter(i=>i.nodeId!==id));selected=''}))}
 if(a==='delete-edge')return change(()=>{m.edges=m.edges.filter(e=>e.id!==selectedEdge);selectedEdge=''});
 if(a==='attribute')return dialog('Atribut descriptiv','<label>Nume<input name="name" required></label><label>Valoare<input name="value" required></label><label>Unitate / format<input name="unit"></label>',d=>change(()=>n(selected).attributes.push(d)));
 if(a==='new-variable')return variableDialog();if(a==='baseline'){baseline={model:structuredClone(m),result:structuredClone(result)};render();return}if(a==='restore')return change(()=>m=structuredClone(baseline.model));if(a==='comparison')return download('scenario-comparison.json',JSON.stringify({baseline,current:{model:m,result}},null,2));if(a==='results-json')return download('simulation-report.json',JSON.stringify({model:m,result},null,2));
 if(a==='results-csv'){const cell=x=>'"'+String(x).replaceAll('"','""')+'"';return download('operations.csv','\ufeff'+[['id','name','processing_ratio','down_ratio','blocked_ratio','queue_mean','resource_wait_s','material_wait_s'],...result.first.operations.map(o=>[o.id,o.name,o.busy,o.down,o.blocked,o.queue,o.resourceWait,o.materialWait])].map(row=>row.map(cell).join(',')).join('\r\n'),'text/csv;charset=utf-8')}
}
function chooseNode(id){if(connectMode){if(!connectFrom){connectFrom=id;selected=id;render();return}completeConnection(connectFrom,id);return}selected=id;selectedEdge='';render()}
function bind(){bindEngineering();document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{page=b.dataset.page;connectFrom='';portFrom=null;render()});document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));document.querySelectorAll('[data-diagram]').forEach(b=>b.onclick=()=>{diagramId=b.dataset.diagram;selectedEdge='';connectFrom='';portFrom=null;render()});
 document.querySelectorAll('[data-edge]').forEach(b=>b.onclick=e=>{e.stopPropagation();selectedEdge=b.dataset.edge;selected='';render()});
 document.querySelectorAll('[data-node]').forEach(g=>{g.onkeydown=e=>{if(e.key==='Enter')chooseNode(g.dataset.node)};g.onpointerdown=e=>{if(e.button!==0||busy)return;const id=g.dataset.node;if(connectMode){chooseNode(id);return}const item=diagram().items.find(i=>i.nodeId===id),start={x:e.clientX,y:e.clientY,ix:item.x,iy:item.y};let moved=false;g.setPointerCapture(e.pointerId);g.onpointermove=ev=>{const dx=(ev.clientX-start.x)/zoom,dy=(ev.clientY-start.y)/zoom;if(Math.abs(dx)+Math.abs(dy)>4)moved=true;if(moved)g.setAttribute('transform',`translate(${Math.max(0,start.ix+dx)},${Math.max(0,start.iy+dy)})`)};g.onpointerup=ev=>{g.onpointermove=null;g.onpointerup=null;if(moved)change(()=>{item.x=Math.max(0,Math.round(start.ix+(ev.clientX-start.x)/zoom));item.y=Math.max(0,Math.round(start.iy+(ev.clientY-start.y)/zoom));selected=id;selectedEdge=''},{layout:true});else chooseNode(id)};g.onpointercancel=()=>render()}});
 for(const key of ['hours','seed','replications'])if($('#'+key))$('#'+key).onchange=e=>change(()=>m.settings[key]=+e.target.value);
 $('#node-form')?.addEventListener('submit',e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));change(()=>{const el=n(selected);el.name=d.name;el.description=d.description;el.parent=d.parent;el.stereotypes=d.stereotypes.split(',').map(s=>s.trim()).filter(Boolean);el.moflt=d.moflt;el.behavior=d.behavior;el.properties=d.properties.split('\n').filter(s=>s.trim()).map(s=>{const eq=s.indexOf('=');const left=eq<0?s:s.slice(0,eq);const colon=left.indexOf(':');return {name:(colon<0?left:left.slice(0,colon)).trim(),type:colon<0?'':left.slice(colon+1).trim(),value:eq<0?'':s.slice(eq+1).trim()}});for(const k of fields(el.type)){if(el.params[k]!==+d['p-'+k]){initializeProvenance(el);el.calibration[k]={status:'assumption',note:'Modificat manual în inspector; confirmă măsurarea în Calibrare.'}}el.params[k]=+d['p-'+k];if(d['b-'+k])el.bindings[k]=d['b-'+k];else delete el.bindings[k]}for(let i=0;i<(el.specs||[]).length;i++)el.specs[i].value=+d['spec-'+i]})});
 $('#edge-form')?.addEventListener('submit',e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));change(()=>{const edge=m.edges.find(x=>x.id===selectedEdge);for(const k of ['weight','delay','quantity','order'])if(k in d)edge[k]=+d[k];for(const k of ['label','guard','trigger','effect','sourceMultiplicity','targetMultiplicity'])if(k in d)edge[k]=d[k]})});
 document.querySelectorAll('[data-attribute]').forEach(b=>b.onclick=()=>change(()=>n(selected).attributes.splice(+b.dataset.attribute,1)));
 document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{const id=b.dataset.open;page='diagrams';selected=id;selectedEdge='';if(!diagram().items.some(i=>i.nodeId===id))change(()=>diagram().items.push({nodeId:id,x:50,y:50}),{layout:true});else render()});
 document.querySelectorAll('[data-var]').forEach(b=>b.onclick=()=>variableDialog(b.dataset.var));document.querySelectorAll('[data-vardelete]').forEach(b=>b.onclick=()=>change(()=>{const id=b.dataset.vardelete;if(m.nodes.some(n=>Object.values(n.bindings).includes(id)))throw Error('Variabila este legată. Elimină legăturile înainte de ștergere.');m.variables=m.variables.filter(v=>v.id!==id)}));
 $('#search')?.addEventListener('change',e=>{search=e.target.value;render()});
 $('#file').onchange=async e=>{if(busy)return;const f=e.target.files[0];if(!f)return;if(f.size>10000000){toast('Maximum 10 MB.');return}try{const next=migrate(JSON.parse(await f.text()));validateModel(next);change(()=>{m=next;diagramId=m.diagrams[0]?.id;selected='';selectedEdge='';storageNote='';baseline=null;cloudId='';cloudRevision=0;connectMode=false;connectFrom='';portFrom=null;initializeAll()})}catch(err){toast('Import respins: '+err.message)}};
}
initializeAll();render();detectRuntime().then(async value=>{runtime=value;if(runtime.mode==='docker'){try{catalog=(await api('/api/catalog')).items}catch(e){toast('Catalogul dedicat nu răspunde; folosesc biblioteca inclusă.')}}render()});
function diagramSvg(){return renderEngineeringDiagram(m,diagram(),{zoom,selected,selectedEdge,portFrom,result,connectMode,connectFrom,colorMode,focusSelection})}



function libraryView(){return renderLibrary({m,catalog,query:librarySearch,category:libraryCategory,libraryMode})}
function staffingView(){return render_staffingView({m,result,baseline,search})}
function engineeringView(){return render_engineeringView({m,result,baseline,search})}
function addToDiagram(el){m.nodes.push(el);const d=diagram(),count=d.items.length;d.items.push({nodeId:el.id,x:50+count%4*250,y:70+Math.floor(count/4)*160});selected=el.id;selectedEdge='';page='diagrams'}
function assignOperator(id){dialog('Operator per utilaj · '+n(id).name,`<label>Operator / echipă<select name="person"><option value="new">+ Creează operator nou</option>${selectOptions(m.nodes.filter(x=>['person','team'].includes(x.type)).map(x=>[x.id,x.name]),'new')}</select></label><label>Nume pentru operator nou<input name="name" value="Operator ${esc(n(id).name)}" required></label><label>Număr necesar per utilaj<input type="number" name="quantity" min="1" max="1000" value="1" required></label><p>Capacitatea operatorului / echipei se configurează separat în inspector.</p>`,d=>change(()=>{let pid=d.person;if(pid==='new'){const p=node('person',d.name);p.params.capacity=+d.quantity;m.nodes.push(p);pid=p.id}m.edges.push({id:uid('staff'),type:'staffedBy',from:id,to:pid,quantity:+d.quantity});if(!diagram().items.some(i=>i.nodeId===pid))diagram().items.push({nodeId:pid,x:60,y:Math.max(0,...diagram().items.map(i=>i.y))+160})}))}
function engineeringAction(a){
 if(a==='assign-operator'){assignOperator(selected);return true}
 if(a==='audit-export'){download('engineering-audit.json',JSON.stringify({findings:modelAudit(m),coverage:DIAGRAMS},null,2));return true}
 if(a==='fit'){const d=diagram();zoom=Math.max(.1,Math.min(1,($('.canvas-scroll')?.clientWidth||800)/Math.max(1450,...d.items.map(i=>i.x+250))));render();return true}
 if(a==='add-port'){dialog('Creează port',`<label>Nume<input name="name" required maxlength="80"></label><label>Tip port<select name="kind">${selectOptions(['proxy','full','standard'].map(x=>[x,x]),'proxy')}</select></label><label>Direcție<select name="direction">${selectOptions(['in','out','inout'].map(x=>[x,x]),'inout')}</select></label><label>Tip flux / payload<input name="payload" placeholder="Part / Status / Command"></label><label>Interfață din model<select name="typeRef"><option value="">Nespecificată</option>${selectOptions(m.nodes.filter(x=>['interfaceBlock','interface'].includes(x.type)).map(x=>[x.id,x.name]),'')}</select></label>`,d=>change(()=>n(selected).ports.push({id:uid('port'),...d})));return true}
 if(a==='save-template'){dialog('Salvează șablon personal','<label>Nume<input name="name" required value="'+esc(n(selected).name)+'"></label><p>Se copiază definiția și valorile efective, fără relații sau legături la variabile. Porturile primesc ID-uri noi la instanțiere. Referințele la interfețe rămân în model.</p>',d=>change(()=>{const element=structuredClone(n(selected));element.params=effective(m,element);element.bindings={};element.parent='';m.library??=[];m.library.push({id:uid('template'),name:d.name,element})}));return true}
 return false;
}
function bindEngineering(){
 const guard=fn=>{if(busy){toast('Anulează simularea înainte de editare.');return}fn()};
 $('#library-search')?.addEventListener('change',e=>{librarySearch=e.target.value;render()});
 document.querySelectorAll('[data-template]').forEach(b=>b.onclick=()=>change(()=>addToDiagram(instantiate(CATALOG.find(t=>t.id===b.dataset.template)))));
 document.querySelectorAll('[data-cell]').forEach(b=>b.onclick=()=>change(()=>{diagram().kind='process';selected=createCell(m,diagram(),CATALOG.find(t=>t.id===b.dataset.cell));selectedEdge='';page='diagrams'}));
 document.querySelectorAll('[data-personal]').forEach(b=>b.onclick=()=>change(()=>{const t=m.library.find(t=>t.id===b.dataset.personal),el=structuredClone(t.element);el.id=uid(el.type);el.name=t.name;el.ports.forEach(p=>p.id=uid('port'));addToDiagram(el)}));
 document.querySelectorAll('[data-templatedelete]').forEach(b=>b.onclick=()=>change(()=>m.library=m.library.filter(t=>t.id!==b.dataset.templatedelete)));
 document.querySelectorAll('[data-staff]').forEach(b=>b.onclick=()=>guard(()=>assignOperator(b.dataset.staff)));
 document.querySelectorAll('[data-staffdelete]').forEach(b=>b.onclick=()=>change(()=>m.edges=m.edges.filter(e=>e.id!==b.dataset.staffdelete)));
 document.querySelectorAll('[data-portdelete]').forEach(b=>b.onclick=()=>change(()=>{const id=b.dataset.portdelete;if(m.edges.some(e=>e.fromPort===id||e.toPort===id))throw Error('Șterge mai întâi conectorii acestui port.');n(selected).ports=n(selected).ports.filter(p=>p.id!==id)}));
 document.querySelectorAll('[data-port]').forEach(b=>{b.onpointerdown=e=>e.stopPropagation();const connect=()=>guard(()=>{const owner=b.dataset.owner,port=b.dataset.port;if(!portFrom){portFrom={owner,port};toast('Selectează portul destinație; click pe același port anulează.');render();return}if(portFrom.port===port){portFrom=null;render();return}const from=portFrom;portFrom=null;const chosen=$('#relation-type').value;const type=['connector','assemblyConnector','delegation','itemFlow','binding'].includes(chosen)?chosen:'connector';if(!DIAGRAMS[diagram().kind].relations.includes(type)){toast('Folosește o vedere IBD / arhitectură / componentă pentru conectarea porturilor.');render();return}change(()=>{const edge={id:uid('edge'),type,from:from.owner,to:owner,fromPort:from.port,toPort:port};m.edges.push(edge);selectedEdge=edge.id;selected=''});});b.onclick=e=>{e.stopPropagation();connect()};b.onkeydown=e=>{if(e.key==='Enter'){e.stopPropagation();connect()}}});
}

function initializeAll(){for(const el of m.nodes)initializeProvenance(el);m.observations??=[]}
function completeConnection(from,to,ports={}){const type=connectionType;let id;const ok=change(()=>{const edge=createConnection(m,{type,from,to,...ports});m.edges.push(edge);id=edge.id;selectedEdge=id;selected=''});if(ok){connectFrom='';portFrom=null;render();toast('Conexiune creată: '+RELATIONS[type]+'. Poți continua sau apăsa Esc.')}}
function configureTemplate(id,cell=false){const t=catalog.find(t=>t.id===id);if(!t)return;const preview=instantiate(t);dialog(cell?'Configurează celula · '+t.name:'Adaugă · '+t.name,`<p>${esc(t.description)}</p><label>Nume<input name="name" value="${esc(t.name)}" required></label>${specificationFields(preview)}<details class="property-section" ${PROCESS.includes(t.type)?'open':''}><summary>Parametri de simulare · configurație locală</summary><p class="small">Aceste valori sunt configurații sau ipoteze, nu valori din fișa comercială.</p>${fields(t.type).map(k=>`<label>${esc(FIELDS[k][0])} (${esc(FIELDS[k][1])})<input name="p-${k}" type="number" step="${['capacity','buffer','limit'].includes(k)?'1':'any'}" min="${FIELDS[k][2]}" max="${FIELDS[k][3]}" value="${k==='cycle'?'':preview.params[k]}" required></label>`).join('')}</details>${cell?`<h3>Procesul piesei</h3><label>Ciclu de procesare (s)<input name="cycle" type="number" min=".01" max="86400" step="any" placeholder="Introdu timpul procesului tău" required></label><label>Interval sosiri (s)<input name="interval" type="number" min="1" max="86400" step="any" required></label><label>Proveniența ciclului<select name="status"><option value="assumption">Ipoteză pentru explorare</option><option value="measured">Măsurat în proces</option></select></label><label>Referință / condiții<input name="note" placeholder="Produs, operație, sursa măsurării" required></label><label>Personal dedicat pe întreg ciclul<select name="operator"><option value="yes">Creează un operator</option><option value="no">Fără operator dedicat</option></select></label>`:''}<p class="small muted">Poți modifica ulterior toate valorile din inspector. Inserarea nu schimbă șablonul producătorului.</p>`,d=>change(()=>{let el;if(cell){diagram().kind='process';connectionType='flow';const mid=createCell(m,diagram(),t,{cycle:+d.cycle,interval:+d.interval,status:d.status,note:d.note,operator:d.operator==='yes'});el=n(mid);selected=mid;selectedEdge='';page='diagrams';}else{el=preview;addToDiagram(el)}el.name=d.name;for(const k of fields(el.type)){el.params[k]=+d['p-'+k];if(el.params[k]!==preview.params[k])el.calibration[k]={status:'assumption',note:'Configurat la inserare.'}}el.specs.forEach((s,i)=>s.value=+d['spec-'+i]);initializeAll()}))}
function calibrateParameter(id,key){const el=n(id),f=FIELDS[key];if(!el||!f)return;const old=el.calibration?.[key];dialog('Calibrare · '+el.name,`<label>${esc(f[0])} (${esc(f[1])})<input name="value" type="number" step="${['capacity','buffer','limit'].includes(key)?'1':'any'}" min="${f[2]}" max="${f[3]}" value="${effective(m,el)[key]}" required></label><label>Proveniență<select name="status">${selectOptions([['measured','Măsurat în proces'],['assumption','Ipoteză documentată'],['required','De calibrat']],old?.status||'required')}</select></label><label>Sursă / condiții / justificare<textarea name="note" required>${esc(old?.note||'')}</textarea></label>${el.bindings[key]?'<p>Se înlocuiește legătura locală la variabilă. Celelalte elemente rămân legate.</p>':''}`,d=>change(()=>{initializeProvenance(el);el.params[key]=+d.value;delete el.bindings[key];el.calibration[key]={status:d.status,note:d.note}}))}
function actionV04(a){
 if(a==='rename-model'){dialog('Numele proiectului','<label>Nume<input name="name" value="'+esc(m.name)+'" required></label>',d=>change(()=>m.name=d.name,{layout:true}));return true}
 if(a==='select-mode'||a==='connect-mode'){connectMode=a==='connect-mode';connectFrom='';portFrom=null;render();return true}
 if(a==='cloud-save'){saveDockerModel();return true}
 if(a==='cloud-models'){loadDockerModels();return true}
 return false;
}
let dockerSaving=false;
async function saveDockerModel(){if(dockerSaving)return;dockerSaving=true;const snapshot=structuredClone(m),id=cloudId||uid('model'),expected=cloudRevision;try{const r=await api('/api/models/'+id,{method:'PUT',data:{model:snapshot,expectedRevision:expected}});cloudId=id;cloudRevision=r.revision;render();toast('Snapshot salvat în Docker · revizia '+r.revision)}catch(e){toast(e.message)}finally{dockerSaving=false}}
async function loadDockerModels(){try{const {items}=await api('/api/models');if(!items.length){toast('Nu există modele salvate în Docker.');return}dialog('Deschide model din Docker',`<p>Modelul curent va fi înlocuit. Exportă-l sau salvează-l înainte; Undo este disponibil.</p><label>Model<select name="id">${selectOptions(items.map(x=>[x.id,x.name+' · r'+x.revision]),items[0].id)}</select></label>`,d=>{api('/api/models/'+d.id).then(record=>{const next=migrate(record.model);validateModel(next);change(()=>{m=next;initializeAll();cloudId=record.id;cloudRevision=record.revision;diagramId=m.diagrams[0].id;selected='';selectedEdge='';baseline=null;page='overview'})}).catch(e=>toast(e.message))})}catch(e){toast(e.message)}}
function bindV04(){
 $('#diagram-colors')?.addEventListener('change',e=>{colorMode=e.target.value;render()});
 $('#focus-selection')?.addEventListener('change',e=>{focusSelection=e.target.checked;render()});
 $('#workspace-role').onchange=e=>{role=e.target.value;page=role==='operator'?'operator':'overview';connectMode=false;connectFrom='';render()};
 $('#relation-type')?.addEventListener('change',e=>{connectionType=e.target.value;portFrom=null});
 $('#library-category')?.addEventListener('change',e=>{libraryCategory=e.target.value;render()});
 $('#library-mode')?.addEventListener('change',e=>{libraryMode=e.target.value;render()});
 $('#operator-operation')?.addEventListener('change',e=>{operatorOperation=e.target.value;render()});
 document.querySelectorAll('[data-configure]').forEach(b=>b.onclick=()=>{if(!busy)configureTemplate(b.dataset.configure)});
 document.querySelectorAll('[data-configure-cell]').forEach(b=>b.onclick=()=>{if(!busy)configureTemplate(b.dataset.configureCell,true)});
 document.querySelectorAll('[data-quick-node]').forEach(b=>b.onclick=()=>{if(!busy)newNode(b.dataset.quickNode)});
 document.querySelectorAll('[data-calibrate]').forEach(b=>b.onclick=()=>{if(!busy)calibrateParameter(b.dataset.calibrate,b.dataset.param)});
 document.querySelectorAll('[data-edit-attribute]').forEach(b=>b.onclick=()=>{if(busy)return;const i=+b.dataset.editAttribute,a=n(selected).attributes[i];dialog('Editează atribut',`<label>Nume<input name="name" value="${esc(a.name)}" required></label><label>Valoare<input name="value" value="${esc(a.value)}" required></label><label>Unitate<input name="unit" value="${esc(a.unit)}"></label>`,d=>change(()=>n(selected).attributes[i]=d))});
 $('#observation-form')?.addEventListener('submit',e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));try{const samples=d.samples.split(/[;\n]+/).map(s=>s.trim()).filter(Boolean).map(Number);if(!samples.length||samples.length>1000||samples.some(v=>!Number.isFinite(v)||v<=0||v>86400))throw Error('Introdu 1–1000 timpi pozitivi, maximum 86400 s fiecare.');const mean=samples.reduce((a,b)=>a+b,0)/samples.length;change(()=>{const op=n(d.operation);op.params.cycle=mean;delete op.bindings.cycle;initializeProvenance(op);op.calibration.cycle={status:'measured',note:d.note};m.observations??=[];m.observations.push({operation:op.id,samples,mean,count:samples.length,note:d.note,at:new Date().toISOString()});if(m.observations.length>1000)m.observations.shift()});if(!lastChangeError)toast('Timpul mediu a fost salvat în model.')}catch(err){toast(err.message)}});
 document.querySelectorAll('[data-connect-start]').forEach(handle=>{const begin=()=>{if(busy)return;connectMode=true;connectFrom=handle.dataset.connectStart;selected=connectFrom;render()};handle.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();e.stopPropagation();begin()}};handle.onpointerdown=e=>{e.stopPropagation();if(busy)return;const from=handle.dataset.connectStart,svg=$('#diagram-canvas'),start={x:e.clientX,y:e.clientY};let moved=false;const ghost=document.createElementNS('http://www.w3.org/2000/svg','path');ghost.setAttribute('stroke','#245DDB');ghost.setAttribute('stroke-width','3');ghost.setAttribute('fill','none');ghost.setAttribute('stroke-dasharray','6 4');ghost.style.pointerEvents='none';svg.append(ghost);const move=ev=>{if(Math.abs(ev.clientX-start.x)+Math.abs(ev.clientY-start.y)>6)moved=true;const rect=svg.getBoundingClientRect();ghost.setAttribute('d',`M${(start.x-rect.left)/zoom} ${(start.y-rect.top)/zoom} L${(ev.clientX-rect.left)/zoom} ${(ev.clientY-rect.top)/zoom}`)};const stop=()=>{document.removeEventListener('pointermove',move);document.removeEventListener('pointerup',up);document.removeEventListener('pointercancel',stop);ghost.remove()};const up=ev=>{const target=document.elementFromPoint(ev.clientX,ev.clientY)?.closest('[data-node]')?.dataset.node;stop();connectMode=true;connectFrom=from;if(moved&&target&&target!==from)completeConnection(from,target);else render()};document.addEventListener('pointermove',move);document.addEventListener('pointerup',up,{once:true});document.addEventListener('pointercancel',stop,{once:true})};handle.onclick=e=>e.stopPropagation()});
 document.onkeydown=e=>{if(e.key==='Escape'){connectMode=false;connectFrom='';portFrom=null;$('.cover')?.remove();render();return}if(e.target.closest('input,textarea,select,[contenteditable]'))return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();action(e.shiftKey?'redo':'undo')}if(e.key==='Delete'&&selectedEdge)action('delete-edge')};
 document.querySelectorAll('.cover').forEach(c=>c.onkeydown=e=>{if(e.key!=='Tab')return;const nodes=[...c.querySelectorAll('button,input,select,textarea,a[href]')].filter(n=>!n.disabled);if(e.shiftKey&&document.activeElement===nodes[0]){e.preventDefault();nodes.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===nodes.at(-1)){e.preventDefault();nodes[0].focus()}});
}

